public class HL7ContinuationHandler {
    public static void handleADDSegments(HL7Message message) throws Exception {
        // Get all ADD segments from the message
        List<HL7Segment> addSegments = message.getSegments("ADD");

        if (addSegments.isEmpty()) {
            System.out.println("No ADD segments found.");
            return;
        }

        // Create a map to store reference numbers and their corresponding segment indices
        Map<String, Integer> refMap = new HashMap<>();

        for (HL7Segment addSegment : addSegments) {
            String refNumber = addSegment.getFieldValue("REF");
            int segmentIndex = addSegment.getIndex();

            if (!refMap.containsKey(refNumber)) {
                refMap.put(refNumber, segmentIndex);
            }
        }

        // Reconstruct the complete message by concatenating all ADD segments
        List<HL7Segment> reconstructedSegments = new ArrayList<>();
        for (String refNumber : refMap.keySet()) {
            int segmentIndex = refMap.get(refNumber);

            HL7Segment addSegment = addSegments.get(segmentIndex);
            reconstructedSegments.add(addSegment);

            // Add the original message's segments before this ADD segment
            List<HL7Segment> originalSegments = message.getSegments();
