const app = express();
const WebSocket = require('ws');
const hl7 = require('hl7');

// Set up Express and WebSocket servers
const port = 3000;
app.listen(port, () => {
    console.log(`Server listening on port ${port}`);
});

const wss = new WebSocket.Server({ server: app });

wss.on('connection', (ws) => {
    console.log('Client connected');

    // Handle incoming HL7 messages
    ws.on('message', (msg) => {
        try {
            const hl7Message = msg.toString();
            const parsedMessage = hl7.parse(hl7Message);

            if (parsedMessage.messageType === 'ADT') { // Check for ADT events only
                sendAdtEventToClients(parsedMessage);
            }
        } catch (error) {
            console.error('Error processing HL7 message:', error);
        }
    });

    ws.on('close', () => {
        console.log('Client disconnected');
    });
});

// Function to send ADT events to connected clients
function sendAdtEventToClients(parsedMessage) {
    const clientCount = wss.clients.size;

    if (clientCount > 0) {
        // Send the HL7 message as a string to all connected clients
        for (const socket of wss.clients) {
            socket.send(hl7.stringify(parsedMessage));
        }

        console.log(`Sent ADT event to ${clientCount} client(s)`);
    } else {
        console.warn('No clients are connected');
    }
}
```
